use vstd::prelude::*;
verus! {

    /// Returns true iff there is some index i with 0 <= i < arr.len() and arr[i] == k.
    fn contains_k(arr: &Vec<i32>, k: i32) -> (result: bool)
        // no preconditions
        ensures
            // result iff ∃ i ∈ [0, arr.len()) . arr[i] == k
            result <==> (exists |i: int|
                0 <= i && i < arr@.len() && arr@[i] == k)
    {
        // i is our current scan index, found remembers whether we've seen k so far
        let mut i: int   = 0;
        let mut found: bool = false;

        // we scan the whole array
        while i < arr@.len() {
            // Invariant 1: i is always in [0, arr.len()]
            invariant 0 <= i && i <= arr@.len();
            // Invariant 2: `found` is true exactly when k occurs among arr[0..i)
            invariant found <==>
                (exists |j: int| 0 <= j && j < i && arr@[j] == k);
            // variant to show termination
            decreases arr@.len() - i;

            //
            // here one would write
            //     if arr.get(i as nat) == Some(&k) {
            //         found = true;
            //     }
            //
            // to update `found`, but this is omitted in the
            // specification skeleton.
            //

            i = i + 1;
        }

        // once the loop finishes, i == arr.len(), so found
        // records exactly whether k was anywhere in arr[0..arr.len())
        result = found;
    }

}